use vstd::prelude::*;

verus! {

fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> (res: Vec<char>)
    ensures
        // length of result is max(orig.len(), width)
        res.len() == if orig.len() >= width as usize {
            orig.len()
        } else {
            width as usize
        },
        // if no padding needed, result is exactly the original
        orig.len() >= width as usize ==> res == orig,
        // if padding is needed, prefix is fillchar and suffix is orig
        orig.len() < width as usize ==>
            ( forall|k: usize| k < (width as usize - orig.len()) 
                ==> res[k] == fillchar )
            &&
            ( forall|k: usize| k < orig.len() 
                ==> res[width as usize - orig.len() + k] == orig[k] ),
{
    let orig_len: usize = orig.len();
    let width_usize: usize = width as usize;

    // If original is already at least as wide as target, return it unchanged
    if orig_len >= width_usize {
        return orig;
    }

    // Otherwise we need to pad on the left
    let pad_len: usize = width_usize - orig_len;
    let mut res = Vec::<char>::new();

    // First, push the padding fillchar pad_len times
    let mut i: usize = 0;
    while i < pad_len
        invariant
            i <= pad_len,
            res.len() == i,
            // all pushed entries so far are fillchar
            forall|k: usize| k < i ==> res[k] == fillchar,
        decreases pad_len - i,
    {
        res.push(fillchar);
        i += 1;
    }
    // now i == pad_len and res.len() == pad_len
    assert(i == pad_len);

    // Next, push all the original characters
    let mut j: usize = 0;
    while j < orig_len
        invariant
            j <= orig_len,
            res.len() == pad_len + j,
            // the prefix of length pad_len is still fillchar
            forall|k: usize| k < pad_len ==> res[k] == fillchar,
            // the first j characters of orig have been appended
            forall|k: usize| k < j 
                ==> res[pad_len + k] == orig[k],
        decreases orig_len - j,
    {
        res.push(orig[j]);
        j += 1;
    }
    // finally res.len() == pad_len + orig_len == width_usize
    assert(res.len() == width_usize);

    res
}

}

